// Extract contact data from AI agent output
const input = $input.item.json;

// Helper function to safely extract field from various formats
function extractField(data, possibleKeys, defaultValue = '') {
  for (const key of possibleKeys) {
    if (data[key] !== undefined && data[key] !== null) {
      const val = data[key];
      // Handle object with value property
      if (typeof val === 'object' && val.value) {
        return String(val.value).trim();
      }
      // Handle direct value
      if (typeof val === 'string' && val.trim()) {
        return val.trim();
      }
      if (typeof val === 'number') {
        return String(val);
      }
    }
  }
  return defaultValue;
}

// Extract all contact fields
const fullName = extractField(input, ['Full_Name', 'Full Name', 'fullName', 'name', 'Name']);
const email = extractField(input, ['Email_Address', 'Email Address', 'email', 'Email']);
const phone = extractField(input, ['Phone_Number', 'Phone Number', 'phone', 'Phone']);
const company = extractField(input, ['Company_Name', 'Company Name', 'company', 'Company']);
const address = extractField(input, ['Address', 'address']);
const summary = extractField(input, ['Client_Summary__AI_', 'Client Summary (AI)', 'Client Summary', 'summary', 'Summary']);
const clientType = extractField(input, ['Client_Type', 'Client Type (AI)', 'Client Type', 'clientType', 'type', 'Type']);
const account = extractField(input, ['Account', 'account']);

// Validation
const errors = [];

if (!fullName) {
  errors.push('Full Name is required');
}

if (!email) {
  errors.push('Email Address is required');
} else {
  // Validate email format
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(email)) {
    errors.push(`Invalid email format: ${email}`);
  }
}

// If there are validation errors, return error object
if (errors.length > 0) {
  return {
    json: {
      success: false,
      error: errors.join(', '),
      message: `Validation failed: ${errors.join(', ')}`
    }
  };
}

// Return clean, validated contact data
return {
  json: {
    success: true,
    'Email Address': email.toLowerCase(),
    'Full Name': fullName,
    'Phone Number': phone,
    'Company Name': company,
    'Address': address,
    'Date Added': new Date().toISOString(),
    'Client Summary (AI)': summary,
    'Client Type (AI)': clientType,
    'Account': account,
    'Photo URL': '',
    'Last Updated': new Date().toISOString()
  }
};

// This node receives all sheet data and searches for matching email
const searchEmail = $input.first().json['Email Address'];
const allRows = $input.all();

// Find matching contact
const matchedRow = allRows.find(row => {
  const rowEmail = row.json['Email Address'];
  return rowEmail && rowEmail.toLowerCase() === searchEmail.toLowerCase();
});

if (matchedRow) {
  // Contact exists - prepare for update
  return {
    json: {
      exists: true,
      rowNumber: matchedRow.json.row_number || matchedRow.json.__row_number,
      email: searchEmail,
      action: 'update',
      ...matchedRow.json
    }
  };
} else {
  // Contact doesn't exist - prepare for create
  return {
    json: {
      exists: false,
      email: searchEmail,
      action: 'create'
    }
  };
}

// Get search criteria (from AI or direct input)
const criteria = $input.first().json;
const searchEmail = criteria.searchEmail || criteria.email || '';
const searchName = criteria.searchName || criteria.name || '';
const searchCompany = criteria.searchCompany || criteria.company || '';

// Get all contacts from previous node
const allContacts = $input.all().slice(1); // Skip first item (criteria)

if (!searchEmail && !searchName && !searchCompany) {
  // No filters - return all
  return allContacts;
}

// Filter contacts
const results = allContacts.filter(contact => {
  const data = contact.json;
  let match = false;

  // Email search (partial match, case insensitive)
  if (searchEmail && data['Email Address']) {
    if (data['Email Address'].toLowerCase().includes(searchEmail.toLowerCase())) {
      match = true;
    }
  }

  // Name search (partial match, case insensitive)
  if (searchName && data['Full Name']) {
    if (data['Full Name'].toLowerCase().includes(searchName.toLowerCase())) {
      match = true;
    }
  }

  // Company search (partial match, case insensitive)
  if (searchCompany && data['Company Name']) {
    if (data['Company Name'].toLowerCase().includes(searchCompany.toLowerCase())) {
      match = true;
    }
  }

  return match;
});

return results;

const data = $input.item.json;
const action = data.action || 'unknown';

return {
  json: {
    success: true,
    action: action,
    message: `Contact ${action === 'create' ? 'created' : 'updated'} successfully`,
    contact: {
      email: data['Email Address'],
      name: data['Full Name'],
      company: data['Company Name'] || 'N/A'
    }
  }
};

const error = $input.item.json.error || 'Unknown error occurred';

return {
  json: {
    success: false,
    error: error,
    message: `Failed to process contact: ${error}`
  }
};
